// Some portions generated by Claude Code
// @ts-check
const { test, expect } = require('@playwright/test');
const { deleteRepository, memoryRepositoryConfiguration, repositoryPageUrl, serverBaseUrl,
    uniqueRepositoryId, waitForRoute } = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('graph-side-panels');
const DATA = `
@prefix ex: <http://example.org/side-panels/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
ex:alice a ex:Person ; rdfs:label "Alice" ; ex:worksFor ex:acme .
ex:bob a ex:Person ; rdfs:label "Bob" ; ex:worksFor ex:acme .
ex:acme a ex:Organization ; rdfs:label "Acme" .
`;

test.beforeAll(async ({ request }) => {
    const endpoint = `${serverBaseUrl()}/repositories/${REPOSITORY_ID}`;
    const created = await request.put(endpoint, { headers: { 'Content-Type': 'text/turtle' },
        data: memoryRepositoryConfiguration(REPOSITORY_ID, 'Graph side panels') });
    expect([200, 201, 204]).toContain(created.status());
    const loaded = await request.post(`${endpoint}/statements`, { headers: { 'Content-Type': 'text/turtle' }, data: DATA });
    expect([200, 204]).toContain(loaded.status());
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

function overlaps(a, b) {
    return a.x < b.x + b.width && b.x < a.x + a.width && a.y < b.y + b.height && b.y < a.y + a.height;
}

test('the details card stays beside the filters when the graph panel narrows with both open', async ({ page }) => {
    await page.setViewportSize({ width: 1600, height: 900 });
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    const explorer = page.locator('.graph-explorer');
    await explorer.getByRole('button', { name: /^Load \d+ statements$/ }).click();
    const alice = explorer.locator('.graph-node').filter({ hasText: 'Alice' }).first();
    await expect(alice).toBeAttached({ timeout: 30000 });
    await explorer.getByRole('button', { name: /Filter graph nodes/ }).click();
    const filters = explorer.locator('#graph-filter-sidebar');
    await expect(filters).toBeVisible();
    await alice.click();
    const details = explorer.locator('.node-details');
    await expect(details.locator('h3')).toHaveText('Alice');
    await expect(filters, 'a wide panel keeps both open').toBeVisible();

    // The query editor and a smaller window narrow the graph panel below 820px, where the filters cover the canvas.
    await explorer.getByRole('button', { name: 'Query editor', exact: true }).click();
    await page.setViewportSize({ width: 1340, height: 900 });
    const panelWidth = await explorer.locator('.graph-panel').evaluate(panel => panel.clientWidth);
    expect(panelWidth).toBeGreaterThan(640);
    expect(panelWidth).toBeLessThanOrEqual(820);
    await expect.poll(async () => overlaps(await details.boundingBox(), await filters.boundingBox()),
        { message: 'the details card is beside the filters' }).toBe(false);

    await explorer.getByRole('button', { name: 'Close details' }).click({ timeout: 5000 });
    await expect(details).toHaveCount(0);
    await expect(filters).toBeVisible();
});
